Imagine you have a circular piece of plywood. You randomly hammer 6 nails into the very edge of the circle. If you wrap a rubber band around those nails, what are the odds that the center of the wood is trapped inside that rubber band?
This is a classic problem in the field of geometric probability. The idea was taken from a youtube video I found online, but can also be found here along with a selection of other super fun puzzles.
Anyway, I’ve attached an interactive version of this puzzle. Feel free to play around with it however you like.
viewof nPoints = Inputs.range([3, 12], {value: 6, step: 1, label: "Number of Points (n)"})

canvas = {
  const width = 400;
  const height = 400;
  const context = DOM.context2d(width, height);
  const radius = 150;
  const center = { x: width / 2, y: height / 2 };

  // Generate random points on the circumference
  const points = Array.from({ length: nPoints }, () =&gt; {
    const angle = Math.random() * Math.PI * 2;
    return {
      x: center.x + radius * Math.cos(angle),
      y: center.y + radius * Math.sin(angle),
      angle: angle
    };
  }).sort((a, b) =&gt; a.angle - b.angle);

  // Check if center is inside: all consecutive gaps must be &lt; PI
  let isInside = true;
  for (let i = 0; i &lt; points.length; i++) {
    const nextIdx = (i + 1) % points.length;
    let gap = points[nextIdx].angle - points[i].angle;
    if (gap &lt; 0) gap += Math.PI * 2;
    if (gap &gt; Math.PI) isInside = false;
  }

  // Drawing
  context.clearRect(0, 0, width, height);

  // Draw Circle
  context.beginPath();
  context.arc(center.x, center.y, radius, 0, Math.PI * 2);
  context.strokeStyle = "#ccc";
  context.stroke();

  // Draw Polygon
  context.beginPath();
  context.moveTo(points[0].x, points[0].y);
  points.forEach(p =&gt; context.lineTo(p.x, p.y));
  context.closePath();
  context.fillStyle = isInside ? "rgba(76, 175, 80, 0.3)" : "rgba(244, 67, 54, 0.3)";
  context.fill();
  context.strokeStyle = isInside ? "#4CAF50" : "#F44336";
  context.stroke();

  // Draw Center
  context.beginPath();
  context.arc(center.x, center.y, 4, 0, Math.PI * 2);
  context.fillStyle = "black";
  context.fill();

  return context.canvas;
}

