app = {
  // 1. Setup the Layout
  const container = html`&lt;div style="display: flex; flex-direction: column; align-items: center;"&gt;
    &lt;div class="controls-container"&gt;
       &lt;div id="slider-container"&gt;&lt;/div&gt;
       &lt;button class="randomize-btn"&gt;Randomize Positions&lt;/button&gt;
    &lt;/div&gt;
    &lt;div id="canvas-container"&gt;&lt;/div&gt;
  &lt;/div&gt;`;

  const sliderContainer = container.querySelector("#slider-container");
  const canvasContainer = container.querySelector("#canvas-container");
  const randBtn = container.querySelector("button");

  // 2. State Variables
  let currentLogic = null; 

  // 3. Helper to Create/Reset the Canvas
  function updateCanvas(n, mode) {
    canvasContainer.innerHTML = ""; // Clear existing canvas
    const c = DOM.canvas(400, 400);
    canvasContainer.appendChild(c);

    // Create new logic and store it
    currentLogic = createInteractiveCircle(c, n, mode);
  }

  // 4. Initialize Slider
  const sliderWrapper = Inputs.range([3, 12], {value: 6, step: 1, label: "Points (n)"});
  sliderContainer.appendChild(sliderWrapper);

  // *** THE FIX *** // We must grab the actual &lt;input&gt; tag inside the wrapper to get .valueAsNumber
  const rangeInput = sliderWrapper.querySelector("input");

  // 5. Event Listener: Slider Change
  rangeInput.addEventListener("input", () =&gt; {
    // Now we get the correct number (e.g., 6) instead of undefined
    updateCanvas(rangeInput.valueAsNumber, "even");
  });

  // 6. Event Listener: Button Click
  randBtn.onclick = () =&gt; {
    if (currentLogic) {
      currentLogic.randomize();
    }
  };

  // 7. Initial Render
  updateCanvas(6, "even");

  return container;
}

