import { createInteractiveCircle } from "./visualization.js"

// 1. Create the container
controls = {
  const container = html`&lt;div class="controls-container"&gt;
    &lt;div id="slider-container"&gt;&lt;/div&gt;
    &lt;div id="button-container"&gt;&lt;/div&gt;
  &lt;/div&gt;`;
  return container;
}

// 2. The Slider
viewof n = {
  const container = controls.querySelector('#slider-container');
  container.innerHTML = ''; 
  const input = Inputs.range([3, 12], {value: 6, step: 1, label: "Points (n)"});
  container.appendChild(input);
  return input;
}

// 3. The Randomize Button
viewof randomize = {
  const container = controls.querySelector('#button-container');
  container.innerHTML = ''; 

  const button = html`&lt;button class="randomize-btn"&gt;Randomize Positions&lt;/button&gt;`;
  container.appendChild(button);

  // Initialize value
  button.value = 0;

  button.onclick = () =&gt; {
    button.value += 1;
    button.dispatchEvent(new Event("input"));
  };

  return button;
}

// 4. The Visualization Logic
visual = {
  // Declare dependencies
  n;
  randomize;

  // CHECK: Can we reuse the existing canvas?
  // We reuse it if the canvas exists (this) AND the number of points (n) hasn't changed.
  if (this && this.n === n) {
    // We are here because 'randomize' changed (button was clicked).
    // Just call the randomize function on the existing logic object.
    if (randomize &gt; this.lastRandomize) {
       this.logic.randomize();
    }

    // Update the tracker so we don't randomize again unnecessarily
    this.lastRandomize = randomize;
    return this; 
  }

  // RESET: If we reach here, either it's the first load OR 'n' has changed.
  // We create a fresh canvas with EVEN spacing.
  const c = DOM.canvas(400, 400);

  // Initialize with "even" and store the logic object to access later
  c.logic = createInteractiveCircle(c, n, "even");

  // Attach state to the canvas DOM element so we can check it next time
  c.n = n;
  c.lastRandomize = randomize;

  return c;
}
